scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

xf:group.script:
/**
* //property handling
* $w.log("id:" + options.id);
* $w.log("class:" + options.class);
* $w.log("gridView:" + options.gridView);
* $w.log("checkColumnId:" + options.checkColumnId);
* $w.log("dataInsertFunction:" + options.dataInsertFunction);
* $w.log("dataDeleteFunction:" + options.dataDeleteFunction);
* $w.log("dataCopyFunction:" + options.dataCopyFunction);
* $w.log("excelUploadFunction:" + options.excelUploadFunction);
* $w.log("excelDownloadFunction:" + options.excelDownloadFunction);
* $w.log("isDataBtn:" + options.isDataBtn);
* $w.log("isExcelBtn:" + options.isExcelBtn);
* $w.log("isTempletBtn:" + options.isTempletBtn);
*
* //event trigger
*/

var UDC_ID = this.id;
var property = udc_obj.options;
var btnInsert, btnDelete, btnCopy, btnExcelDown, btnExcelUpload, btnTempletDown;
var gridViewComp, dataListComp;
var excD_isBatchUse, excD_inBatchID, excD_inParams, excD_isWait, excD_strHidden, excD_isBatchOnly, excD_isSkipEnc;
var excU_strHidden;

scwin.init = function(options) {
    var wfmId = "";

    if (typeof property.gridView !== "undefined") {

        var grdView = options.gridView;


        if(typeof scwin.$w !== "undefined"){
            var grids = WebSquare.wUnit.getJq("div[id$='"+grdView+"']");
            for(var i=0; i<grids.length; i++){
                var gridId = grids.get(i).id;
                var temp = gridId.replace("_"+grdView,"");
                if(options.id.indexOf(temp) > -1){
                    wfmId = temp;
                    break;
                }

            }

            if(String(wfmId).length > 0){
                grdView = wfmId + "_" + grdView;
                property.gridView = grdView;
            }
        }

        gridViewComp = WebSquare.wUnit.getObjById(grdView);
        var dataListId = gridViewComp.getDataList();
        if (typeof dataListId !== "undefined") {
            dataListComp = WebSquare.wUnit.getObjById(dataListId);
        }
    }

    btnInsert = WebSquare.wUnit.getObjById(UDC_ID + "_btnInsert");
    btnDelete = WebSquare.wUnit.getObjById(UDC_ID + "_btnDelete");
    btnCopy = WebSquare.wUnit.getObjById(UDC_ID + "_btnCopy");
    btnExcelDown = WebSquare.wUnit.getObjById(UDC_ID + "_btnExcelDown");
    btnExcelUpload = WebSquare.wUnit.getObjById(UDC_ID + "_btnExcelUpload");
    btnTempletDown = WebSquare.wUnit.getObjById(UDC_ID + "_btnTempletDown");

    btnInsert.bind("onclick", function(e) {
        if ((typeof property.dataInsertFunction !== "undefined") && (typeof property.dataInsertFunction !== "")) {
            var argument = {
                "gridID" : property.gridView
            };

            if (scwin && ngmf.getMyWframeId(scwin) != "") {
                var func = eval(property.dataInsertFunction);
                if (func && typeof func != "undefined") {
                    func(argument);
                } else {
                    ngmf.executeFunc(property.dataInsertFunction, argument);
                }
            } else {
                ngmf.executeFunc(property.dataInsertFunction, argument);
            }

        } else {
            var rowIndex = udc_obj.setInsertRow();
            gridViewComp.setFocusedCell(rowIndex, 0);
        }
    });
    btnDelete.bind("onclick", function(e) {
        if ((typeof property.dataDeleteFunction !== "undefined") && (typeof property.dataDeleteFunction !== "")) {
            var argument = {
                "gridID" : property.gridView
            };

            if (scwin && ngmf.getMyWframeId(scwin) != "") {
                var func = eval(property.dataDeleteFunction);
                if (func && typeof func != "undefined") {
                    func(argument);
                } else {
                    ngmf.executeFunc(property.dataDeleteFunction, argument);
                }
            } else {
                ngmf.executeFunc(property.dataDeleteFunction, argument);
            }
        } else {
            udc_obj.setDeleteRow();
        }
    });
    btnCopy.bind("onclick", function(e) {
        if ((typeof property.dataCopyFunction !== "undefined") && (typeof property.dataCopyFunction !== "")) {
            var argument = {
                "gridID" : property.gridView
            };
            if (scwin && ngmf.getMyWframeId(scwin) != "") {
                var func = eval(property.dataCopyFunction);
                if (func && typeof func != "undefined") {
                    func(argument);
                } else {
                    ngmf.executeFunc(property.dataCopyFunction, argument);
                }
            } else {
                ngmf.executeFunc(property.dataCopyFunction, argument);
            }
        } else {
            udc_obj.setCopyRow();
        }
    });

    btnExcelDown.bind("onclick", function(e) {
        if ((typeof property.excelDownloadFunction !== "undefined") && (typeof property.excelDownloadFunction !== "")) {
            var argument = {
                "gridID" : property.gridView
            };
            if (scwin && ngmf.getMyWframeId(scwin) != "") {
                var func = eval(property.excelDownloadFunction);
                if (func && typeof func != "undefined") {
                    func(argument);
                } else {
                    ngmf.executeFunc(property.excelDownloadFunction, argument);
                }
            } else {
                ngmf.executeFunc(property.excelDownloadFunction, argument);
            }
        } else {
            udc_obj.excelDonwload();
        }
    });
    btnExcelUpload.bind("onclick", function(e) {
        if ((typeof property.excelUploadFunction !== "undefined") && (typeof property.excelUploadFunction !== "")) {
            var argument = {
                "gridID" : property.gridView
            };
            if (scwin && ngmf.getMyWframeId(scwin) != "") {
                var func = eval(property.excelUploadFunction);
                if (func && typeof func != "undefined") {
                    func(argument);
                } else {
                    ngmf.executeFunc(property.excelUploadFunction, argument);
                }
            } else {
                ngmf.executeFunc(property.excelUploadFunction, argument);
            }
        } else {
            udc_obj.excelUpload();
        }
    });
    btnTempletDown.bind("onclick", function(e) {
        if ((typeof property.templetDownloadFunction !== "undefined") && (typeof property.templetDownloadFunction !== "")) {
            var argument = {
                "gridID" : property.gridView
            };
            if (scwin && ngmf.getMyWframeId(scwin) != "") {
                var func = eval(property.templetDownloadFunction);
                if (func && typeof func != "undefined") {
                    func(argument);
                } else {
                    ngmf.executeFunc(property.templetDownloadFunction, argument);
                }
            } else {
                ngmf.executeFunc(property.templetDownloadFunction, argument);
            }
        } else {
           // udc_obj.templetDown()
        }
    });

    if ((typeof property.showInsertBtn !== "undefined") && (WebSquare.util.getBoolean(property.showInsertBtn))) {
        btnInsert.show("");
    } else {
        btnInsert.hide("");
    }

    if ((typeof property.showDeleteBtn !== "undefined") && (WebSquare.util.getBoolean(property.showDeleteBtn))) {
        btnDelete.show("");
    } else {
        btnDelete.hide("");
    }

    if ((typeof property.showCopyBtn !== "undefined") && (WebSquare.util.getBoolean(property.showCopyBtn))) {
        btnCopy.show("");
    } else {
        btnCopy.hide("");
    }

    if ((typeof property.showExcelDownBtn !== "undefined") && (WebSquare.util.getBoolean(property.showExcelDownBtn))) {
        btnExcelDown.show("");
        btnExcelUpload.show("");
    } else {
        btnExcelDown.hide("");
        btnExcelUpload.hide("");
    }

    if ((typeof property.showExcelUploadBtn !== "undefined") && (WebSquare.util.getBoolean(property.showExcelUploadBtn))) {
        btnExcelUpload.show("");
    } else {
        btnExcelUpload.hide("");
    }

    if ((typeof property.showTempletBtn !== "undefined") && (WebSquare.util.getBoolean(property.showTempletBtn))) {
        btnTempletDown.show("");
    } else {
        btnTempletDown.hide("");
    }

    if (typeof property.tooltip_Insert !== "undefined") {
        btnInsert.options.toolTip = property.tooltip_Insert;
        btnInsert.setToolTip();
    }
    if (typeof property.tooltip_Delete !== "undefined") {
        btnDelete.options.toolTip = property.tooltip_Delete;
        btnDelete.setToolTip();
    }
    if (typeof property.tooltip_Copy !== "undefined") {
        btnCopy.options.toolTip = property.tooltip_Copy;
        btnCopy.setToolTip();
    }
    if (typeof property.tooltip_ExcelDown !== "undefined") {
        btnExcelDown.options.toolTip = property.tooltip_ExcelDown;
        btnExcelDown.setToolTip();
    }
    if (typeof property.tooltip_ExcelUp !== "undefined") {
        btnExcelUpload.options.toolTip = property.tooltip_ExcelUp;
        btnExcelUpload.setToolTip();
    } 
    if (typeof property.tooltip_TempleDown !== "undefined") {
        btnTempletDown.options.toolTip = property.tooltip_TempleDown;
        btnTempletDown.setToolTip();
    } 

    if (typeof property.excelDownloadOption_isBatchUse !== "undefined") {
        excD_isBatchUse = property.excelDownloadOption_isBatchUse;
    } else {
        excD_isBatchUse = false;
    }
    if (typeof property.excelDownloadOption_inBatchID !== "undefined") {
        excD_inBatchID = property.excelDownloadOption_inBatchID;
    } else {
        excD_inBatchID = "";
    }
    if (typeof property.excelDownloadOption_inParams !== "undefined") {
        excD_inParams = property.excelDownloadOption_inParams;
    } else {
        excD_inParams = "";
    }
    if (typeof property.excelDownloadOption_isWait !== "undefined") {
        excD_isWait = property.excelDownloadOption_isWait;
    } else {
        excD_isWait = false;
    }
    if (typeof property.excelDownloadOption_strHidden !== "undefined") {
        excD_strHidden = property.excelDownloadOption_strHidden;
    } else {
        excD_strHidden = "";
    }
    if (typeof property.excelDownloadOption_isBatchOnly !== "undefined") {
        excD_isBatchOnly = property.excelDownloadOption_isBatchOnly;
    } else {
        excD_isBatchOnly = false;
    }
    if (typeof property.excelDownloadOption_isSkipEnc !== "undefined") {
        excD_isSkipEnc = property.excelDownloadOption_isSkipEnc;
    } else {
        excD_isSkipEnc = false;
    }

    if (typeof property.excelUploadOption_strHidden !== "undefined") {
        excU_strHidden = property.excelUploadOption_strHidden;
    } else {
        excU_strHidden = "";
    }
};

/**
   * 설정 그리드의 체크된 row를 추가하는 API 입니다. 체크된 컬럼이 없을 경우 최하단의 row에 추가가 됩니다.
   * @date 2015-12-21
   * @author 이동규
   * @example udcBtnId.setInsertRow();  
   */ 
udc_obj.setInsertRow= function() {
    var dataCompId = dataListComp.id;
    var chkCol = (typeof udc_obj.options.checkColumnId !== "undefined") ? udc_obj.options.checkColumnId : false;
    var rowIndx = -1;
    if (chkCol) {
        if (dataListComp.cellIdList.indexOf(chkCol) < 0 && gridViewComp.cellIdList.indexOf(chkCol) > -1) {
            dataListComp.insertColumn(chkCol);
        }
        var valueType = dataListComp.getCellInfo(chkCol).options.valueType || gridViewComp.getCellInfo(chkCol).options.valueType;
        var trueValue = "1";
        if (valueType == "other") {
            trueValue = "Y";
        } else if (valueType == "boolean") {
            trueValue = true;
        }
       rowIndx = ngmf.insRow(dataListComp.id, chkCol, trueValue);
       dataListComp.setCellData(rowIndx, chkCol, trueValue);
       //gridView1.setColumnReadOnly(chkCol, false);
    } else {
        var rowCount = dataListComp.getTotalRow();
        rowIndx = dataListComp.insertRow(rowCount);
        //추후 삭제 될부분
        gridViewComp.setColumnReadOnly(chkCol, false);
    }
    return rowIndx;
};

 /**
   * 설정 그리드의 체크된 row를 삭제하는 API 입니다.
   * @date 2015-12-21
   * @author 이동규
   * @example udcBtnId.setDeleteRow();  
   */ 
udc_obj.setDeleteRow= function() {
    var dataCompId = dataListComp.id;
    var chkCol = (typeof udc_obj.options.checkColumnId !== "undefined") ? udc_obj.options.checkColumnId : false;
    var rowIndx = -1;
    if (chkCol) {
        var valueType = dataListComp.getCellInfo(chkCol).options.valueType || gridViewComp.getCellInfo(chkCol).options.valueType;
        var trueValue = "1";
        if (valueType == "other") {
            trueValue = "Y";
        } else if (valueType == "boolean") {
            trueValue = true;
        }
        rowIndx = ngmf.delRow(dataListComp.id, chkCol, trueValue);    
    }
    return rowIndx;
};

/**
  * 설정 그리드의 체크된 row를 복사하는 API 입니다.
  * @date 2015-12-21
  * @author 이동규
  * @example udcBtnId.setCopyRow();  
  */  
udc_obj.setCopyRow= function() {
    var dataCompId = dataListComp.id;
    var chkCol = (typeof udc_obj.options.checkColumnId !== "undefined") ? udc_obj.options.checkColumnId : false;
    var rowIndx = -1;
    if (chkCol) {
        var valueType = dataListComp.getCellInfo(chkCol).options.valueType || gridViewComp.getCellInfo(chkCol).options.valueType;
        var trueValue = "1";
        if (valueType == "other") {
            trueValue = "Y";
        } else if (valueType == "boolean") {
            trueValue = true;
        }  
        rowIndx = ngmf.copyRow(dataListComp.id, chkCol, trueValue);    
    }
    return rowIndx;
};

/**
  * 설정 그리드의 데이터를 엑셀파일로 다운로드하는 API 입니다.
  * @date 2015-12-21
  * @author 이동규
  * @example udcBtnId.excelDonwload();  
  */  
udc_obj.excelDonwload= function() {
    var gridId = property.gridView;
    var dataId = ngmf.object(gridId).getDataList();
    //var chk_col_ID = (typeof udc_obj.options.checkColumnId !== "undefined") ? udc_obj.options.checkColumnId : undefined;

    if (typeof gridId != "undefined" && typeof dataId != "undefined") {
        ngmf.popupExcelExport(gridId, dataId, excD_isBatchUse, excD_inBatchID, excD_inParams, excD_isWait, excD_strHidden, excD_isBatchOnly, excD_isSkipEnc);
    }
};

/**
  * 설정 그리드의 데이터를 엑셀파일로 업로드하는 API 입니다.
  * @date 2015-12-21
  * @author 이동규
  * @example udcBtnId.excelUpload(grdId);  
  */  
udc_obj.excelUpload = function() {
    var gridId = property.gridView;
    if (typeof gridId != "undefined") {
        ngmf.popupExcelImport(gridId, excU_strHidden, function(grdId) {
            udc_obj.trigger("onExcelImport", [grdId]);
        }); 
    }
};

/**
  * 설정 버튼의 템플릇을 다운로드하는 API 입니다.
  * @date 2015-12-21
  * @author 이동규
  * @example udcBtnId.templetDown();  
  */  
udc_obj.templetDown= function() {
    var gridId = property.gridView;
    if (typeof gridId != "undefined") {
        ngmf.popupTempletExport(gridId);
    }
};

/**
  * 그리드 하단 버튼을 숨기는 API 입니다.
  * @date 2015-12-21
  * @param {Obejct || String || Number} list : 숨길 버튼들의 정보(배열 또는 String 또는 Number)
  *                                                                     삽입 : "btnInsert" || "0" ||  0   
  *                                                                     삭제 : "btnDelete" || "1" || 1 
  *                                                                     복사 : "btnCopy" || "2" || 2
  *                                                                     엑셀다운로드 : "btnExcelDown" || "3" || 3
  *                                                                     엑셀 업로드   : "btnExcelUpload" || "4" || 4
  *                                                                     템플릿 다운로드 : "btnTempletDown" || "5" || 5
  * @author 이동규
  * @example udcBtnId.hideBtnList(["btnInsert", "btnDelete", "3", 4]); //아무형식 사용화면 됨. 
  */  
udc_obj.hideBtnList = function (list) {
    if (ngmf.isArray(list)) {
        for (var i = 0 ; i < list.length; i++) {
            scwin.btnManager( list[i] , false);
        }
    } else {
        scwin.btnManager( list, false);
    }
};

/**
 * 그리드 하단 버튼을 나타내는 API 입니다.
 * @date 2015-12-21
 * @param {Obejct || String || Number} list : 나타낼 버튼들의 정보(배열 또는 String 또는 Number)
 *                                                                      삽입 : "btnInsert" || "0" ||  0   
 *                                                                      삭제 : "btnDelete" || "1" || 1 
 *                                                                      복사 : "btnCopy" || "2" || 2
 *                                                                      엑셀다운로드 : "btnExcelDown" || "3" || 3
 *                                                                      엑셀 업로드   : "btnExcelUpload" || "4" || 4
 *                                                                      템플릿 다운로드 : "btnTempletDown" || "5" || 5
 * @author 이동규
 * @example udcBtnId.showBtnList(["btnInsert", "btnDelete", "3", 4]); //아무형식 사용화면 됨.
 */
udc_obj.showBtnList = function ( list ) {
    if (ngmf.isArray(list)) {
        for (var i = 0 ; i < list.length; i++) {
            scwin.btnManager( list[i] , true);
        }
    } else {
        scwin.btnManager( list, true);
    }
};

scwin.btnManager = function( type, visible ) {
    var btnComp = "";
    switch (type) {
        case 0 :
        case "0" :
        case "btnInsert" :
            btnComp = btnInsert;
            break;
        case 1 :
        case "1" :
        case "btnDelete" :
            btnComp = btnDelete;
            break;
        case 2 :
        case "2" :
        case "btnCopy" :
            btnComp = btnCopy;
            break;
        case 3 :
        case "3" :
        case "btnExcelDown" :
            btnComp = btnExcelDown;
            break;
        case 4 :
        case "4" :
        case "btnExcelUpload" :
            btnComp = btnExcelUpload;
            break;
        case 5 :
        case "5" :
        case "btnTempletDown" :
            btnComp = btnTempletDown;
            break;
    }

    if (visible ) {
        btnComp.show("");
    } else {
        btnComp.hide();
    }
};

scwin.init(options);
